import{d as g,C as e,o as h,c as u,a3 as i,E as s,j as t,a as m}from"./chunks/framework.Q4yG9rk_.js";const c=JSON.parse('{"title":"论语·颜渊","description":"《论语》第 12 篇「颜渊」——二十四章原文与导读。克己复礼为仁、己所不欲勿施于人、君君臣臣父父子子、民无信不立、君子成人之美。","frontmatter":{"title":"论语·颜渊","description":"《论语》第 12 篇「颜渊」——二十四章原文与导读。克己复礼为仁、己所不欲勿施于人、君君臣臣父父子子、民无信不立、君子成人之美。","category":"guide","aliases":["颜渊","颜渊篇","颜渊第十二","论语颜渊","lunyu 颜渊"],"source":["《论语》"],"outline":[2,3]},"headers":[],"relativePath":"lizhimingde/sishu-wujing/lunyu/chapter-12.md","filePath":"lizhimingde/sishu-wujing/lunyu/chapter-12.md","lastUpdated":1790316338000}'),d={name:"lizhimingde/sishu-wujing/lunyu/chapter-12.md"},x=g({...d,setup(y){const a=[{id:"yi",label:"一、克己复礼为仁",showLabel:!0,sentences:[["颜渊问仁。子曰：“",{text:"克己复礼",glossary:"kejifuli"},"为仁。一日克己复礼，天下归仁焉。为仁由己，而由人乎哉？”颜渊曰：“请问其目？”子曰：“非礼勿视，非礼勿听，非礼勿言，非礼勿动。”颜渊曰：“回虽不敏，请事斯语矣。”"]],note:"颜渊问仁。孔子说：「克己复礼为仁」——约束自己、使言行合于礼，就是仁。「一日克己复礼，天下归仁焉」——一旦如此，天下人心都归向仁。「为仁由己，而由人乎哉」——行仁全靠自己，难道靠别人？颜渊问其条目，答：「非礼勿视，非礼勿听，非礼勿言，非礼勿动」。此为《论语》论仁最核心的一章。"},{id:"er",label:"二、己所不欲，勿施于人",showLabel:!0,sentences:[["仲弓问仁。子曰：“出门如见大宾，使民如承大祭。",{text:"己所不欲，勿施于人",glossary:"jisuobuyu"},"。在邦无怨，在家无怨。”仲弓曰：“雍虽不敏，请事斯语矣。”"]],note:"仲弓问仁。孔子说：「出门如见大宾，使民如承大祭」——出门如会见贵宾，役使百姓如承当大祭。「己所不欲，勿施于人」——自己所不想要的，不要施加于人。「在邦无怨，在家无怨」——在诸侯之国无人怨恨，在卿大夫之家亦无人怨恨。此章以「敬」与「恕」言仁。"},{id:"san",label:"三、仁者，其言也讱",showLabel:!0,sentences:[["司马牛问仁，子曰：“仁者，其言也",{text:"讱",glossary:"ren-ren"},"。”曰：“其言也讱，斯谓之仁已乎？”子曰：“为之难，言之得无讱乎？”"]],note:"司马牛问仁。孔子说：「仁者，其言也讱」——仁者说话是慎重的（讱＝言语迟钝，此谓慎言）。又问：「其言也讱，斯谓之仁已乎」——说话慎重便算是仁了吗？答：「为之难，言之得无讱乎」——做起来难，说起来能不慎重吗？"},{id:"si",label:"四、君子不忧不惧",showLabel:!0,sentences:[["司马牛问君子，子曰：“君子不忧不惧。”曰：“不忧不惧，斯谓之君子已乎？”子曰：“",{text:"内省不疚",glossary:"neixingbujiu"},"，夫何忧何惧？”"]],note:"司马牛问君子。孔子说：「君子不忧不惧」。问：「不忧不惧，斯谓之君子已乎」？答：「内省不疚，夫何忧何惧」——自我反省而无所愧疚，还忧愁畏惧什么呢？"},{id:"wu",label:"五、四海之内皆兄弟也",showLabel:!0,sentences:[["司马牛忧曰：“人皆有兄弟，我独亡。”子夏曰：“商闻之矣：死生有命，富贵在天。君子敬而无失，与人恭而有礼，",{text:"四海之内皆兄弟也",glossary:"sihaixiongdi"},"。君子何患乎无兄弟也？”"]],note:"司马牛忧曰：「人皆有兄弟，我独亡（无）」——人人都有兄弟，独我没有。子夏说：「商闻之矣：死生有命，富贵在天」——我听说：死生由命，富贵在天。「君子敬而无失，与人恭而有礼，四海之内皆兄弟也」——君子敬慎而无过失，待人恭敬而合礼，则四海之内皆兄弟。「君子何患乎无兄弟也」——何必忧虑没有兄弟？"},{id:"liu",label:"六、浸润之谮，肤受之愬",showLabel:!0,sentences:[["子张问明。子曰：“",{text:"浸润之谮",glossary:"jinrunzhizen"},"，",{text:"肤受之愬",glossary:"fushouzhisu"},"，不行焉，可谓明也已矣；浸润之谮、肤受之愬不行焉，可谓远也已矣。”"]],note:"子张问「明」（明察）。孔子说：「浸润之谮，肤受之愬，不行焉，可谓明也已矣」——如水浸润般渐积的谗言、如切肤之痛般急切的诬告，在你这里都行不通，便可说是「明」了；这两种在你这里都行不通，便可说是「远」（有远见）了。"},{id:"qi",label:"七、民无信不立",showLabel:!0,sentences:[["子贡问政。子曰：“足食，足兵，民信之矣。”子贡曰：“必不得已而去，于斯三者何先？”曰：“去兵。”子贡曰：“必不得已而去，于斯二者何先？”曰：“去食。自古皆有死，",{text:"民无信不立",glossary:"minwuxinbuli"},"。”"]],note:"子贡问政。孔子说：「足食，足兵，民信之矣」——粮食足、军备足、百姓信任政府。问不得已须去其一，先去哪项？答「去兵」。再去其一？答：「去食。自古皆有死，民无信不立」——去食；自古以来人皆有一死，但百姓不信任政府，国家便立不住。"},{id:"ba",label:"八、文犹质也，质犹文也",showLabel:!0,sentences:[["棘子成曰：“君子质而已矣，何以文为？”子贡曰：“惜乎，夫子之说君子也！",{text:"驷不及舌",glossary:"sibujishe"},"。文犹质也，质犹文也。虎豹之",{text:"鞟",glossary:"kuo"},"犹犬羊之鞟。”"]],note:"棘子成说：「君子质而已矣，何以文为」——君子只要有好的本质就够了，要文采做什么？子贡说：「惜乎，夫子之说君子也！驷不及舌」——可惜啊，您竟这样论君子！一言既出，四马之车也追不回。「文犹质也，质犹文也。虎豹之鞟犹犬羊之鞟」——文采犹如本质，本质犹如文采；若去掉毛色花纹，虎豹之皮与犬羊之皮便一样了（鞟＝去毛之皮）。"},{id:"jiu",label:"九、百姓足，君孰与不足",showLabel:!0,sentences:[["哀公问于有若曰：“年饥，用不足，如之何？”有若对曰：“",{text:"盍彻乎",glossary:"hechehu"},"？”曰：“二，吾犹不足，如之何其彻也？”对曰：“百姓足，君孰与不足？百姓不足，君孰与足？”"]],note:"哀公问有若：「年饥，用不足，如之何」——年成不好，用度不足，怎么办？有若答：「盍彻乎」——何不行行「彻」法（十分取一之田税）？哀公说：「二，吾犹不足，如之何其彻也」——取二分我尚且不足，怎能只取一分？答：「百姓足，君孰与不足？百姓不足，君孰与足」——百姓富足，君上与谁不富足？百姓不足，君上与谁富足？"},{id:"shi",label:"十、主忠信，徙义",showLabel:!0,sentences:[["子张问崇德辨惑。子曰：“主忠信，",{text:"徙义",glossary:"xiyi"},"，崇德也。爱之欲其生，恶之欲其死；既欲其生，又欲其死，是惑也。‘诚不以富，亦只以异。’”"]],note:"子张问崇德、辨惑。孔子说：「主忠信，徙义，崇德也」——以忠信为主，向义靠拢，便是崇德。「爱之欲其生，恶之欲其死；既欲其生，又欲其死，是惑也」——爱之欲其生，恶之欲其死；既欲其生又欲其死，这就是惑。末引《诗》「诚不以富，亦只以异」（实非因富，只因心志有异）。"},{id:"shiyi",label:"十一、君君，臣臣，父父，子子",showLabel:!0,sentences:[["齐景公问政于孔子。孔子对曰：“君君，臣臣，父父，子子。”公曰：“善哉！信如君不君、臣不臣、父不父、子不子，虽有粟，吾得而食诸？”"]],note:"齐景公问政。孔子答：「君君，臣臣，父父，子子」——君像君，臣像臣，父像父，子像子（各尽其分）。景公说：「善哉！信如君不君、臣不臣、父不父、子不子，虽有粟，吾得而食诸」——对啊！若真个君不君、臣不臣……纵然有粟，我能吃得上吗？（是时齐景公失政、陈氏专权，故有感。）"},{id:"shier",label:"十二、片言可以折狱者",showLabel:!0,sentences:[["子曰：“片言可以折狱者，其由也与？”子路",{text:"无宿诺",glossary:"wususuo"},"。"]],note:"「片言可以折狱者，其由也与」——只凭片言只语便能断案者，大概只有仲由吧！「子路无宿诺」——子路没有拖延不践的诺言（宿＝留滞）。"},{id:"shisan",label:"十三、必也使无讼乎",showLabel:!0,sentences:[["子曰：“听讼，吾犹人也。必也使",{text:"无讼",glossary:"wusong"},"乎。”"]],note:"「听讼，吾犹人也。必也使无讼乎」——审理诉讼，我同别人一样；所望者，必使百姓无讼啊。（与《大学》「听讼」章相通。）"},{id:"shisi",label:"十四、居之无倦，行之以忠",showLabel:!0,sentences:[["子张问政。子曰：“居之无倦，行之以忠。”"]],note:"子张问政。孔子说：「居之无倦，行之以忠」——居其位而不懈怠，行事以忠。"},{id:"shiwu",label:"十五、博学于文，约之以礼",showLabel:!0,sentences:[["子曰：“博学于文，约之以礼，亦可以弗畔矣夫。”"]],note:"「博学于文，约之以礼，亦可以弗畔矣夫」——广泛学习文献，以礼约束自己，也就可不背离道了。（与《雍也》第二十七章重出。）"},{id:"shiliu",label:"十六、君子成人之美",showLabel:!0,sentences:[["子曰：“",{text:"君子成人之美",glossary:"junzichengrenzhimei"},"，不成人之恶；小人反是。”"]],note:"「君子成人之美，不成人之恶；小人反是」——君子成全别人的好事，不促成别人的坏事；小人正相反。"},{id:"shiqi",label:"十七、政者，正也",showLabel:!0,sentences:[["季康子问政于孔子。孔子对曰：“政者，正也。子",{text:"帅",glossary:"shuai"},"以正，孰敢不正？”"]],note:"季康子问政。孔子答：「政者，正也。子帅以正，孰敢不正」——政即是正；您带头行正，谁敢不正？"},{id:"shiba",label:"十八、苟子之不欲，虽赏之不窃",showLabel:!0,sentences:[["季康子患盗，问于孔子。孔子对曰：“苟子之不欲，虽赏之不窃。”"]],note:"季康子苦于盗贼，问孔子。孔子答：「苟子之不欲，虽赏之不窃」——若您自己不贪求，纵然奖赏他们去偷，他们也不会偷。"},{id:"shijiu",label:"十九、君子之德风，小人之德草",showLabel:!0,sentences:[["季康子问政于孔子曰：“如杀无道，以就有道，何如？”孔子对曰：“子为政，焉用杀？子欲善，而民善矣。",{text:"君子之德风，小人之德草",glossary:"junzizhidefeng"},"，草上之风必",{text:"偃",glossary:"yan-dao"},"。”"]],note:"季康子问政：「如杀无道，以就有道，何如」——若杀掉无道之人，以成就有道之人，如何？孔子答：「子为政，焉用杀？子欲善，而民善矣」——您为政，何必用杀？您想向善，百姓便向善了。「君子之德风，小人之德草，草上之风必偃」——在上者之德如风，百姓之德如草；草上加风，必倒伏（偃＝倒伏）。"},{id:"ershi",label:"二十、是闻也，非达也",showLabel:!0,sentences:[["子张问：“士何如斯可谓之达矣？”子曰：“何哉尔所谓达者？”子张对曰：“在邦必闻，在家必闻。”子曰：“是闻也，非达也。夫达也者，质直而好义，察言而观色，虑以下人。在邦必达，在家必达。夫闻也者，色取仁而行违，居之不疑。在邦必闻，在家必闻。”"]],note:"子张问：「士何如斯可谓之达矣」——士怎样才算「达」？孔子问：「何哉尔所谓达者」——你所说的达指什么？子张答：「在邦必闻，在家必闻」——在诸侯之国必有名望，在卿大夫之家必有名望。孔子说：「是闻也，非达也」——那是「闻」，不是「达」。「夫达也者，质直而好义，察言而观色，虑以下人」——所谓达：品质正直而好义，察言观色，常思谦退待人；「在邦必达，在家必达」。「夫闻也者，色取仁而行违，居之不疑」——至于闻：面色装取于仁而行实相违，还安然自居不疑。此章辨「闻」（虚名）与「达」（实德）。"},{id:"ershiyi",label:"二十一、先事后得",showLabel:!0,sentences:[["樊迟从游于舞雩之下，曰：“敢问崇德、",{text:"修慝",glossary:"xiute"},"、辨惑。”子曰：“善哉问！先事后得，非崇德与？攻其恶，无攻人之恶，非修慝与？一朝之忿，忘其身，以及其亲，非惑与？”"]],note:"樊迟从游于舞雩之下，问：「敢问崇德、修慝、辨惑」——请问怎样崇德、去除恶念、辨别迷惑（慝＝恶念）？孔子说：「善哉问」！「先事后得，非崇德与」——先做事而后收获，不就是崇德吗？「攻其恶，无攻人之恶，非修慝与」——反省自己的过恶，不攻击别人的过恶，不就是修慝吗？「一朝之忿，忘其身，以及其亲，非惑与」——因一时的愤怒而忘其身，以至连累亲人，不就是惑吗？"},{id:"ershier",label:"二十二、爱人，知人",showLabel:!0,sentences:[["樊迟问仁。子曰：“爱人。”问知。子曰：“知人。”樊迟未达。子曰：“举直错诸枉，能使枉者直。”樊迟退，见子夏，曰：“乡也吾见于夫子而问知，子曰：‘举直错诸枉，能使枉者直’，何谓也？”子夏曰：“富哉言乎！舜有天下，选于众，举",{text:"皋陶",glossary:"gaoyao"},"，不仁者远矣。汤有天下，选于众，举",{text:"伊尹",glossary:"yiyin"},"，不仁者远矣。”"]],note:"樊迟问仁。孔子说：「爱人」。问智，答：「知人」。樊迟未达。孔子说：「举直错诸枉，能使枉者直」——举用正直者、置于邪枉者之上，能使邪枉者归于正直。樊迟退下，见子夏曰：「乡（向）也吾见于夫子而问知，子曰『举直错诸枉，能使枉者直』，何谓也」？子夏曰：「富哉言乎」——此言的含蕴多富啊！「舜有天下，选于众，举皋陶，不仁者远矣；汤有天下，选于众，举伊尹，不仁者远矣」——舜有天下，从众人中举出皋陶，不仁者便远离了；汤有天下，从众人中举出伊尹，不仁者亦远离了。"},{id:"ershisan",label:"二十三、忠告而善道之",showLabel:!0,sentences:[["子贡问友。子曰：“忠告而善道之，不可则止，毋自辱焉。”"]],note:"子贡问交友。孔子说：「忠告而善道之，不可则止，毋自辱焉」——忠心地劝告、好好地引导；若不听便止，不要自取其辱。"},{id:"ershisi",label:"二十四、以文会友，以友辅仁",showLabel:!0,sentences:[["曾子曰：“君子以文会友，以友辅仁。”"]],note:"曾子说：「君子以文会友，以友辅仁」——君子以文章学问聚会朋友，以朋友辅助自己的仁德。全篇以此收束。"}],r=[{id:"kejifuli",term:"克己复礼",pinyin:"kè jǐ fù lǐ",meaning:"约束自己，使言行归于礼。克：约束、克制；复：回归。朱注：「克，胜也；己，谓身之私欲也。」"},{id:"jisuobuyu",term:"己所不欲，勿施于人",pinyin:"jǐ suǒ bù yù， wù shī yú rén",meaning:"自己不想要的，不要加给别人。这是「恕」的正面表述，也是孔子之道「一以贯之」的一半。"},{id:"ren-ren",term:"讱",pinyin:"rèn",meaning:"言语迟钝、说话谨慎（此处指因知难而不轻言）。"},{id:"neixingbujiu",term:"内省不疚",pinyin:"nèi xǐng bù jiù",meaning:"自己反省而没有愧疚。疚：内心痛苦、惭愧。"},{id:"sihaixiongdi",term:"四海之内皆兄弟也",pinyin:"sì hǎi zhī nèi， jiē xiōng dì yě",meaning:"天下之大，人人皆可如兄弟。这是子夏对司马牛「无兄弟」之忧的回答。"},{id:"jinrunzhizen",term:"浸润之谮",pinyin:"jìn rùn zhī zèn",meaning:"像水浸润一样慢慢渗透的谗言。谮：谗言、诬陷。"},{id:"fushouzhisu",term:"肤受之愬",pinyin:"fū shòu zhī sù",meaning:"像切肤之痛一样直接急切的诬告。愬：同「诉」，控告。"},{id:"minwuxinbuli",term:"民无信不立",pinyin:"mín wú xìn bù lì",meaning:"百姓不信任（政府），国家就站不住。孔子在食、兵、信三者中去食存信，见其对「信」的分量。"},{id:"sibujishe",term:"驷不及舌",pinyin:"sì bù jí shé",meaning:"四匹马拉的车也追不上舌头（说出的话）。驷：四马所驾之车。"},{id:"kuo",term:"鞟",pinyin:"kuò",meaning:"去毛的皮。虎豹之鞟犹犬羊之鞟：去掉毛色花纹，虎豹的皮和犬羊的皮就没有分别了——喻文不可废。"},{id:"hechehu",term:"盍彻乎",pinyin:"hé chè hū",meaning:"何不实行「彻」的税法（什一之税）？盍：何不；彻：周代什一之税。"},{id:"xiyi",term:"徙义",pinyin:"xǐ yì",meaning:"趋向于义、见义则迁。徙：迁移、跟从。"},{id:"wususuo",term:"无宿诺",pinyin:"wú sù nuò",meaning:"不把承诺拖到第二天。宿：隔夜、滞留。子路答应的事，当天就办。"},{id:"wusong",term:"无讼",pinyin:"wú sòng",meaning:"没有诉讼。听讼是治标，使民无讼才是治本。"},{id:"junzichengrenzhimei",term:"君子成人之美",pinyin:"jūn zǐ chéng rén zhī měi",meaning:"君子成全别人的好事，不促成别人的坏事。"},{id:"shuai",term:"帅",pinyin:"shuài",meaning:"同「率」，带头、以身作则。"},{id:"junzizhidefeng",term:"君子之德风，小人之德草",pinyin:"jūn zǐ zhī dé fēng， xiǎo rén zhī dé cǎo",meaning:"上位者的德行像风，百姓的德行像草——风吹到草上，草一定倒伏。喻在上者以身作则的力量。"},{id:"yan-dao",term:"偃",pinyin:"yǎn",meaning:"倒伏。"},{id:"xiute",term:"修慝",pinyin:"xiū tè",meaning:"治去自己隐藏的恶念。慝：藏于心的恶。"},{id:"gaoyao",term:"皋陶",pinyin:"gāo yáo",meaning:"舜时的贤臣，掌刑法。"},{id:"yiyin",term:"伊尹",pinyin:"yī yǐn",meaning:"商汤时的贤相。"}];return(p,n)=>{const o=e("DaoTextReading"),l=e("DaoKeywordCards");return h(),u("div",null,[n[0]||(n[0]=i("",6)),s(o,{colophon:"颜渊第十二 · 二十四章",tone:"ink",sections:a,glossary:r,"default-mode":"slips","aria-label":"论语·颜渊 原文"}),n[1]||(n[1]=t("h2",{id:"【原典层】注音与字词",tabindex:"-1"},[m("【原典层】注音与字词 "),t("a",{class:"header-anchor",href:"#【原典层】注音与字词","aria-label":'Permalink to "【原典层】注音与字词"'},"​")],-1)),s(l,{items:[{term:"克己复礼",pinyin:["kè","jǐ","fù","lǐ"],meaning:"约束自己，使言行归于礼。克：约束、克制；复：回归。朱注：「克，胜也；己，谓身之私欲也。」"},{term:"己所不欲，勿施于人",pinyin:["jǐ","suǒ","bù","yù，","wù","shī","yú","rén"],meaning:"自己不想要的，不要加给别人。这是「恕」的正面表述，也是孔子之道「一以贯之」的一半。"},{term:"讱",pinyin:["rèn"],meaning:"言语迟钝、说话谨慎（此处指因知难而不轻言）。"},{term:"内省不疚",pinyin:["nèi","xǐng","bù","jiù"],meaning:"自己反省而没有愧疚。疚：内心痛苦、惭愧。"},{term:"四海之内皆兄弟也",pinyin:["sì","hǎi","zhī","nèi，","jiē","xiōng","dì","yě"],meaning:"天下之大，人人皆可如兄弟。这是子夏对司马牛「无兄弟」之忧的回答。"},{term:"浸润之谮",pinyin:["jìn","rùn","zhī","zèn"],meaning:"像水浸润一样慢慢渗透的谗言。谮：谗言、诬陷。"},{term:"肤受之愬",pinyin:["fū","shòu","zhī","sù"],meaning:"像切肤之痛一样直接急切的诬告。愬：同「诉」，控告。"},{term:"民无信不立",pinyin:["mín","wú","xìn","bù","lì"],meaning:"百姓不信任（政府），国家就站不住。孔子在食、兵、信三者中去食存信，见其对「信」的分量。"},{term:"驷不及舌",pinyin:["sì","bù","jí","shé"],meaning:"四匹马拉的车也追不上舌头（说出的话）。驷：四马所驾之车。"},{term:"鞟",pinyin:["kuò"],meaning:"去毛的皮。虎豹之鞟犹犬羊之鞟：去掉毛色花纹，虎豹的皮和犬羊的皮就没有分别了——喻文不可废。"},{term:"盍彻乎",pinyin:["hé","chè","hū"],meaning:"何不实行「彻」的税法（什一之税）？盍：何不；彻：周代什一之税。"},{term:"徙义",pinyin:["xǐ","yì"],meaning:"趋向于义、见义则迁。徙：迁移、跟从。"},{term:"无宿诺",pinyin:["wú","sù","nuò"],meaning:"不把承诺拖到第二天。宿：隔夜、滞留。子路答应的事，当天就办。"},{term:"无讼",pinyin:["wú","sòng"],meaning:"没有诉讼。听讼是治标，使民无讼才是治本。"},{term:"君子成人之美",pinyin:["jūn","zǐ","chéng","rén","zhī","měi"],meaning:"君子成全别人的好事，不促成别人的坏事。"},{term:"帅",pinyin:["shuài"],meaning:"同「率」，带头、以身作则。"},{term:"君子之德风，小人之德草",pinyin:["jūn","zǐ","zhī","dé","fēng，","xiǎo","rén","zhī","dé","cǎo"],meaning:"上位者的德行像风，百姓的德行像草——风吹到草上，草一定倒伏。喻在上者以身作则的力量。"},{term:"偃",pinyin:["yǎn"],meaning:"倒伏。"},{term:"修慝",pinyin:["xiū","tè"],meaning:"治去自己隐藏的恶念。慝：藏于心的恶。"},{term:"皋陶",pinyin:["gāo","yáo"],meaning:"舜时的贤臣，掌刑法。"},{term:"伊尹",pinyin:["yī","yǐn"],meaning:"商汤时的贤相。"}]}),n[2]||(n[2]=i("",21))])}}});export{c as __pageData,x as default};
